// AgentCapabilities defines model for AgentCapabilities.
type AgentCapabilities struct {
	Arch    AgentCapabilitiesArch `json:"arch"`
	Backups *bool                 `json:"backups,omitempty"`
	Build   *bool                 `json:"build,omitempty"`

	// BuildCache Supports bounded project-scoped layer caches. Agents send this extension only after a controller response advertises Astilba-Agent-Build-Cache with v1.
	BuildCache *bool `json:"buildCache,omitempty"`

	// BuildControls Supports explicit build budgets and frozen-commit watch paths. Agents send this extension only after a controller response advertises Astilba-Agent-Features with build-controls.
	BuildControls *bool `json:"buildControls,omitempty"`

	// BuildNetwork Runs builds on its owned build network behind the build egress policy. Advertised only after Astilba-Agent-Build-Network v1.
	BuildNetwork *bool `json:"buildNetwork,omitempty"`
	Compose      *bool `json:"compose,omitempty"`

	// CredentialFreeVisualCancel Agent accepts visual cancellation without re-sending hydrated credentials.
	CredentialFreeVisualCancel *bool `json:"credentialFreeVisualCancel,omitempty"`

	// CrossHost Supports versioned managed private links and coordinated cross-host commands.
	CrossHost *bool `json:"crossHost,omitempty"`
	Docker    bool  `json:"docker"`

	// KeyProtection How the agent protects its key. setup_required and seal_failed mean it holds none yet, so it keeps its bearer credential. Advertised only after Astilba-Agent-Keys v1.
	KeyProtection *AgentCapabilitiesKeyProtection `json:"keyProtection,omitempty"`

	// KeyStoreProblem Why the agent's key store is unavailable, as the agent logs it. Advertised only after Astilba-Agent-Keys v1.
	KeyStoreProblem *string `json:"keyStoreProblem,omitempty"`

	// MachineBoundRotation Agent names its enrolled machine when rotating its credential. Advertised only after Astilba-Agent-Machine-Rotation v1.
	MachineBoundRotation *bool `json:"machineBoundRotation,omitempty"`

	// MaintenanceContinuation Supports stateful maintenance writer resumption after its admission deadline with primary-first delivery.
	MaintenanceContinuation *bool  `json:"maintenanceContinuation,omitempty"`
	Os                      string `json:"os"`

	// Previews Supports bounded preview plans and ownership-verified cleanup.
	Previews *bool `json:"previews,omitempty"`

	// PrimaryIngress Moves its ingress proxy onto the dedicated gateway when a reviewed coordinated plan makes this host primary. Advertised only after Astilba-Agent-Primary-Ingress v1.
	PrimaryIngress *bool                     `json:"primaryIngress,omitempty"`
	Protocol       AgentCapabilitiesProtocol `json:"protocol"`

	// RailpackVersion Supported Railpack planner/frontend version. Agents send this extension only after a controller response advertises Astilba-Agent-Railpack with v1.
	RailpackVersion *string `json:"railpackVersion,omitempty"`

	// Replicas Supports replica recipe 3 and complete instance groups. Advertised only after Astilba-Agent-Replicas v1.
	Replicas *bool `json:"replicas,omitempty"`

	// SafeReleases Supports instance-based stateless HTTP releases. Advertised only after Astilba-Agent-Safe-Releases v1.
	SafeReleases *bool `json:"safeReleases,omitempty"`

	// Schedules Supports general schedule formats and bounded job cleanup. Advertised only after Astilba-Agent-Schedules v1.
	Schedules *bool `json:"schedules,omitempty"`

	// ServiceOutputs Supports named service output references; advertised only after Astilba-Agent-Service-Outputs v1.
	ServiceOutputs *bool `json:"serviceOutputs,omitempty"`

	// Troubleshooting Supports terminal sessions. Advertised only after Astilba-Agent-Troubleshooting v2.
	Troubleshooting *bool `json:"troubleshooting,omitempty"`

	// TroubleshootingEnabled The host owner has opted in to terminal sessions. Advertised only after Astilba-Agent-Troubleshooting v2.
	TroubleshootingEnabled *bool `json:"troubleshootingEnabled,omitempty"`

	// TroubleshootingUnavailable Why a current agent cannot offer terminal sessions on this host. Advertised only after Astilba-Agent-Troubleshooting v2.
	TroubleshootingUnavailable *AgentCapabilitiesTroubleshootingUnavailable `json:"troubleshootingUnavailable,omitempty"`
	Upgrades                   *bool                                        `json:"upgrades,omitempty"`
	Version                    string                                       `json:"version"`
	Visual                     *bool                                        `json:"visual,omitempty"`
}

